package com.learnagent.quiz;import com.learnagent.memory.FlashcardService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/quizzes")public class QuizController{private final QuizService service;private final FlashcardService flashcards;public QuizController(QuizService service,FlashcardService flashcards){this.service=service;this.flashcards=flashcards;}@PostMapping("/generate")public ResponseEntity<QuizDtos.QuizView> generate(@Valid@RequestBody QuizDtos.GenerateRequest r){Quiz q=service.generate(r);return ResponseEntity.status(HttpStatus.CREATED).body(service.get(q.getId()));}@GetMapping public List<QuizDtos.QuizView> list(@RequestParam(required=false)UUID courseId){return service.list(courseId);}@GetMapping("/{id}")public QuizDtos.QuizView get(@PathVariable UUID id){return service.get(id);}@PostMapping("/{id}/submit")public QuizDtos.Submission submit(@PathVariable UUID id,@Valid@RequestBody QuizDtos.SubmitRequest r){QuizDtos.Submission result=service.submit(id,r);flashcards.fromSubmission(id,result);return result;}}
